// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);

        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.Deposit{value: 2 ether}();

        // Bob has 0 balance, tries to CashOut 1 ether (will fail due to insufficient balance)
        bool ok;
        vm.prank(bob);
        try c.CashOut(1 ether) { ok = true; } catch { ok = false; }

        // In reference: revert due to balance check (ok == false), bob's balance stays 0
        // In buggy: subtraction before check causes underflow (balances[bob] becomes type(uint256).max)
        // So assert that bob's balance is 0 (reference behavior) - bug would have type(uint256).max
        assertTrue(c.balances(bob) == 0, "Bob's balance should be 0");
    }
}

